package net.runelite.client.plugins.microbot.kspbryophyta;
import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.InputStream;
import java.util.Base64;

/** Equipment paper-doll image with an embedded fallback for source-loader builds. */
final class BryophytaEquipmentAssets
{
    private static final String[] EQUIPMENT_IMAGE_BASE64 = {
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            ""
    };

    private BryophytaEquipmentAssets() {}

    static BufferedImage loadEquipmentSlots()
    {
        try (InputStream resource = BryophytaEquipmentAssets.class.getResourceAsStream("equipment_slots.png"))
        {
            if (resource != null)
            {
                BufferedImage image = ImageIO.read(resource);
                if (image != null)
                {
                    return image;
                }
            }
        }
        catch (Exception ignored)
        {
        }

        try
        {
            StringBuilder encoded = new StringBuilder();
            for (String chunk : EQUIPMENT_IMAGE_BASE64)
            {
                encoded.append(chunk);
            }
            byte[] bytes = Base64.getDecoder().decode(encoded.toString());
            return ImageIO.read(new ByteArrayInputStream(bytes));
        }
        catch (Exception ignored)
        {
            return null;
        }
    }
}
